import{defineComponent as e,computed as r,h as n,resolveComponent as t}from"vue";import{useStores as l}from"@directus/extensions-sdk";const i=["Medlem","Arkivar","Administrator"],s=[{t:"Kom godt i gang",b:["Logearkivet er logens fælles register over genstande, arkivmateriale og bøger, med billeder og scanninger. Du åbner det i en browser på computer, tablet eller mobil, når du er på samme netværk som arkivets computer.",{l:["Menuen ligger i den mørke bjælke til venstre. På en smal skærm (mobil) åbner du den med menuknappen øverst; tryk på den mørke flade for at lukke menu og sidepanel igen.","Nederst i bjælken finder du din egen profil, hvor du kan skifte kodeord og logge ud.","Vejledningen her viser kun de funktioner, du selv har adgang til."]},{max:0,v:"Som medlem kan du se og søge i arkivet, men ikke rette i det. Du ser de poster og billeder, som din grad giver adgang til; poster til højere grader vises slet ikke."},{n:1,max:1,v:"Som arkivar ser du alle poster uanset grad, og du kan oprette og rette poster, placeringer og billeder. Du kan ikke slette; det kan kun en administrator."},{n:2,v:"Som administrator kan du alt: oprette brugere, sætte deres grad, slette poster og ændre opsætningen."}]},{t:"Søg i arkivet",b:["Siden Søg (forstørrelsesglasset i menuen) søger i genstande, arkiv og bibliotek på én gang, mens du skriver.",{l:["Flere ord: alle ordene skal findes i posten. Store og små bogstaver er ligegyldige.","Knapperne Alt, Genstande, Arkiv og Bibliotek afgrænser søgningen til én samling.","Placering: vælg trin for trin (rum, montre, hylde). En valgt placering dækker også alt, der står under den.",'"Søg i": vælg Alle felter eller ét bestemt felt, fx Titel, Land eller Forfatter.','Felter med faste valg søges på teksten: "tysk" finder poster med landet Tyskland.',"Uden søgeord vises alt i den valgte samling eller placering, så siden også kan bruges til at se, hvad der står et bestemt sted.","Tryk på et resultat for at åbne posten."]},"Søgningen dækker også søgeord og teksten inde i de PDF-filer på arkivmateriale, som arkivaren har valgt at gøre søgbare (og som har et tekstlag). Du finder kun tekst i de dokumenter, din grad giver adgang til.","Søgningen dækker ikke datoer eller teksten i billeder, scannede PDF'er uden tekstlag og PDF'er, der ikke er valgt til søgning, og talfelter som Udgivelsesår kræver det præcise tal."]},{t:"Se poster under Indhold",b:["Under Indhold (kassen øverst i menuen) ligger samlingerne som lister:",{l:["Genstande: museumsgenstande med inventarnummer, titel, status, land, kategori, datering, materiale, mål, stand, proveniens og billeder.","Arkivmateriale: dokumenter med arkivnummer, dokumenttype, titel, dato, beskrivelse og scanninger.","Bibliotek: bøger med titel, forfatter, udgivelsesår, udgiver, ISBN, sprog, antal eksemplarer, status og omslagsbillede.","Placeringer: rum, montrer, skabe, hylder osv. Listen står i samme orden som placeringerne i virkeligheden, med den fulde kode forrest."]},"Tryk på en række for at åbne posten. Tryk på et billede i posten for at se det stort.",{l:["Sortér ved at trykke på en kolonneoverskrift.","Vælg kolonner med + yderst til højre i overskriftsrækken, eller skjul en kolonne fra dens overskrift. Dit valg huskes.","Søgefeltet øverst i en liste søger kun i den ene samling; brug siden Søg til at søge på tværs."]}]},{t:"Numre, koder og placeringer",b:["Hver placering har en kort kode, og koderne sættes sammen ned gennem træet: FV-M1-H2 er Forværelset (FV), Montre 1 (M1), Hylde 2 (H2). BV er en bagvæg og US et underskab.","Genstande og arkivmateriale får nummer efter deres placering plus et løbenummer: FV-M1-H2-003 er den tredje post på den hylde. Nummeret fortæller altså, hvor posten skal stå.",{n:1,v:"Nummeret tildeles automatisk, når posten gemmes. Flytter du en post til en anden placering, får den et nyt nummer, og en eventuel mærkat på genstanden skal skrives om."}]},{t:"Grader og adgang",b:[{max:0,v:"Hver post har en mindste-grad. Du ser posten og dens billeder, hvis din egen grad er lig med eller højere end postens. Når du får en højere grad, sætter administratoren den på din bruger, og de nye poster dukker op af sig selv."},{n:1,v:"Hver post har feltet Min. grad. Et medlem ser kun posten og dens billeder, hvis medlemmets grad er lig med eller højere. Hæver du Min. grad på en post, mister medlemmer under graden straks adgangen, også til billederne."},{n:1,v:"Et billede, der ikke er knyttet til nogen post, er skjult for medlemmer. Vælg derfor Min. grad med omhu, og knyt altid billeder til den rigtige post."}]},{t:"Registrér en genstand",n:1,b:[{trin:["Gå til Indhold, vælg Genstande, og tryk på + øverst til højre.","Placering: vælg trin for trin, hvor genstanden står (rum, montre, hylde). Placeringen skal vælges; nummeret dannes ud fra den.","Titel: en kort, sigende betegnelse.","Status: I arkiv, Udstillet eller Udlånt.","Min. grad: den laveste grad, der må se genstanden.","Beskrivelse og Land. Danmark er forvalgt; åbn listen og skriv de første bogstaver for at finde et andet land.","Udfyld de øvrige felter efter behov: kategori, datering, materiale, mål, stand, proveniens og noter.","Gem med fluebenet øverst til højre. Inventarnummeret tildeles nu automatisk."]},"Findes placeringen ikke endnu, så opret den først under Ny placering."]},{t:"Registrér arkivmateriale og bøger",n:1,b:["Arkivmateriale og bøger oprettes på samme måde under Indhold: vælg samlingen, tryk +, udfyld felterne og gem.",{l:["Arkivmateriale får arkivnummer automatisk ud fra placeringen, ligesom genstande. Scanninger lægges i feltet med filer.","Bøger har ikke noget automatisk nummer. Angiv titel, forfatter og antal eksemplarer, og læg gerne et omslagsbillede på.","Husk Min. grad på hver post."]}]},{t:"Søgeord og tekst fra PDF'er",n:1,b:["Teksten i en PDF læses kun, hvis du vælger det for den enkelte fil. Uden dit valg bliver filen ikke læst, og der gemmes ingen tekst fra den.",{trin:["Læg PDF'en på posten under Filer/scanninger, og gem posten.","Sæt hak ved filen under Søgbar tekst lige nedenunder. Hakket gemmes med det samme, og teksten læses i løbet af få sekunder.","Genindlæs posten for at se resultatet."]},"Fjerner du hakket igen, slettes teksten fra den fil og de forslag, der byggede på den. De søgeord, du selv har godkendt, bliver stående.",{l:['Tekststatus viser, hvordan det gik: OK, "Ingen tekst fundet – kræver OCR" (en scanning uden tekstlag), "Ikke valgt til søgning" (ingen af postens filer har hak), "Ikke en PDF" eller Fejl.',"Udtrukket tekst (nederst, foldet sammen) er den tekst, der kan søges i. Den kan ikke rettes.","Foreslåede søgeord er maskinens forslag ud fra teksten. De er kun forslag.","Søgeord er de godkendte søgeord. Skriv dine egne, eller tryk Brug foreslåede søgeord under Flows i sidepanelet til højre: forslagene lægges til dem, du allerede har, og du fjerner selv dem, der ikke passer.","Udtræk tekst igen (samme sted) læser de valgte PDF'er på ny, fx hvis teksten ikke svarer til filerne."]},"Bogmærket Kræver OCR under Indhold → Arkivmateriale viser de dokumenter, der ikke kunne læses. Dem kan der kun søges i via titel, beskrivelse og søgeord."]},{t:"Tag billede",n:1,b:["Siden Tag billede (kameraet i menuen) er lavet til mobilen, så du kan fotografere direkte ved montren.",{trin:["Vælg Genstande eller Arkivmateriale øverst.","Find posten: gå ned gennem placeringerne, eller søg på nummer eller titel.","Tryk på posten. Du ser de billeder, den allerede har.","Tryk Tag billede. Kameraet åbner; tag billedet og godkend det.","Billedet overføres og knyttes til posten. Gentag for flere billeder."]},"Du kan også lægge billeder på fra computeren: åbn posten under Indhold og brug feltet Billeder."]},{t:"Opret og ret placeringer",n:1,b:["Siden Ny placering opretter en placering og dens hylder i ét hug.",{trin:["Vælg, hvor den nye placering skal ligge (øverste niveau eller inde i et rum, en montre osv.).",'Vælg type og skriv et navn, fx "Montre 6".',"Koden foreslås automatisk (M6); ret den, hvis du vil. Kun bogstaverne A-Z og tal, og koden skal være unik på sit niveau.","Angiv antal hylder, og sæt flueben ved bagvæg og/eller underskab, hvis montren har det.","Kontrollér forhåndsvisningen nederst, og tryk Opret."]},"En eksisterende placering rettes under Indhold, Placeringer. Ændrer du en kode eller flytter en placering, får alle poster under den nye numre."]},{t:"Ret og flyt poster",n:1,b:[{l:["Åbn posten under Indhold eller via Søg, ret felterne, og gem med fluebenet.","Flyt en post ved at vælge en ny placering. Nummeret skifter, så det passer til den nye plads.","Fjern et billede fra en post i feltet Billeder. Selve filen bliver liggende i filbiblioteket.",{max:1,v:"Du kan ikke slette poster eller filer. Bed en administrator om det."}]}]},{t:"Filbibliotek",n:1,b:["Filbiblioteket (mappen i menuen) viser alle uploadede billeder og scanninger. Normalt lægger du filer på direkte fra en post eller via Tag billede; brug kun filbiblioteket til at finde eller efterse filer. Kun billeder og PDF-filer kan uploades."]},{t:"Brugere og grader",n:2,b:[{trin:["Gå til Brugermappe (personerne i menuen), og tryk + for at oprette en bruger.","Udfyld navn, e-mail og et kodeord, som brugeren selv skifter bagefter.","Vælg rolle: Medlem (kun læse), Arkivar (oprette og rette) eller Administrator.","Sæt brugerens Grad. Den afgør, hvilke poster et medlem kan se.","Gem."]},"Når et medlem får en ny grad, retter du blot feltet Grad på brugeren. En bruger, der har uploadet filer, kan ikke slettes, før filerne er slettet eller brugeren i stedet sættes inaktiv."]},{t:"Menuen for hver rolle",n:2,b:['Du bestemmer, hvilke menupunkter hver rolle ser: Indstillinger, Brugerroller, vælg rollen, og sæt flueben under "Skjul i menuen". Administratorer ser altid hele menuen.',"Det styrer kun menuen, ikke rettighederne. Tag billede og Ny placering er altid skjult for brugere, der ikke må oprette. Brugeren skal genindlæse siden, før en ændring ses."]},{t:"Slet og ryd op",n:2,b:["Kun administratorer kan slette. Åbn posten eller filen og brug skraldespanden øverst, eller markér flere rækker i en liste. Sletning kan ikke fortrydes; tag en backup først, hvis du er i tvivl.","En placering bør kun slettes, når der ikke længere står poster eller underplaceringer på den."]},{t:"Drift: start, adgang og backup",n:2,b:["Arkivet kører på arkivets Chromebook og er kun tilgængeligt, mens den er tændt, og Linux-miljøet kører.",{l:["Start: brug genvejen Logearkiv i Chromebookens appstarter. Den starter systemet og åbner det i browseren.","Adgang fra mobiler: portvideresendelsen af port 8055 slås fra, hver gang Chromebooken eller Linux-miljøet genstartes. Slå den til igen under Indstillinger, Om ChromeOS, Udviklere, Linux-udviklingsmiljø, Portvideresendelse.","Backup: kør ./scripts/backup.sh i mappen logearkiv. Den gemmer database og filer i mappen backup og beholder de 7 nyeste. Kopiér backups til en anden disk, og opbevar filen .env et sikkert sted for sig.","Gendannelse: ./scripts/restore.sh med backup-mappen som parameter. Den overskriver alt nuværende indhold.",'Opgradér ikke Directus, selvom den viser "Update available"; version 12 kan ikke filtrere på grad uden licens.']},"Forbindelsen er endnu ikke krypteret (HTTP), så brug kun arkivet på logens eget netværk. De tekniske detaljer står i README.md i mappen logearkiv."]}],d={page:{padding:"16px",maxWidth:"720px",margin:"0 auto",fontSize:"16px",lineHeight:1.55},hvem:{padding:"12px",borderRadius:"8px",border:"1px solid var(--theme--border-color)",marginBottom:"16px"},afsnit:{borderBottom:"1px solid var(--theme--border-color)",padding:"4px 0"},titel:{cursor:"pointer",padding:"12px 0",fontSize:"18px",fontWeight:"bold"},liste:{margin:"8px 0",paddingLeft:"24px"}};var a={id:"vejledning",name:"Vejledning",icon:"menu_book",routes:[{path:"",component:e({setup(){const{useUserStore:e,usePermissionsStore:a}=l(),g=e().currentUser,o=a(),k=r(()=>g?.admin_access?2:o.hasPermission("genstande","create")?1:0),m=e=>k.value>=(e.n??0)&&k.value<=(e.max??2),u=e=>e.filter(e=>"string"==typeof e||m(e)).map(e=>n("li",{style:"margin:4px 0"},"string"==typeof e?e:e.v)),p=e=>"string"==typeof e?n("p",{style:"margin:8px 0"},e):m(e)?e.l?n("ul",{style:d.liste},u(e.l)):e.trin?n("ol",{style:d.liste},u(e.trin)):n("p",{style:"margin:8px 0"},e.v):null;return()=>{const e=[g?.first_name,g?.last_name].filter(Boolean).join(" ")||g?.email||"",r=[n("div",{style:d.hvem},[n("strong",`${e} · ${i[k.value]}`),0===k.value&&null!=g?.grad?` · grad ${g.grad}`:"",n("div",{style:"font-size:14px;opacity:.7"},"Vejledningen viser de funktioner, du har adgang til. Tryk på en overskrift for at folde afsnittet ud.")])];return s.filter(m).forEach((e,t)=>r.push(n("details",{style:d.afsnit,open:0===t},[n("summary",{style:d.titel},e.t),n("div",{style:"padding-bottom:12px"},e.b.map(p))]))),n(t("private-view"),{title:"Vejledning"},{default:()=>n("div",{style:d.page},r)})}}})}]};export{a as default};
